/* EQIL guard 1.0 (2026-09-28). Shared block, identical in every sim except SEED.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   Review: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md */
var __eqilGuard = (function () {
    var SEED = "287";
    var MODE = "";   // blank mode: the sim addresses options by position, so no inserted placeholder and no shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        var nv = 0, nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var v = String(values[i]).trim(), t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if (v !== "" && !isNaN(Number(v))) { nv++; }
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nv === texts.length || nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    function doSelect(sel, roundChanged) {
        var opts = sel.options, real = [], ph = null, fresh = false, i;
        for (i = 0; i < opts.length; i++) {
            if (isPlaceholder(opts[i])) { if (!ph) { ph = opts[i]; } continue; }
            real.push(opts[i]);
            if (!opts[i].__eqil) { fresh = true; }
        }
        if (real.length < 2) { return; }
        sel.__eqilManaged = true;
        var none = ph ? ph.value : "";
        if (fresh) {
            var before = sel.value, prev = sel.__eqilLast, wasUser = sel.__eqilUser && !roundChanged;
            if (!ph && MODE !== "blank") {
                ph = document.createElement("option");
                ph.value = "";
                ph.disabled = true;
                ph.setAttribute("data-eqil-ph", "1");
                sel.insertBefore(ph, sel.firstChild);
            }
            var texts = [], values = [];
            for (i = 0; i < real.length; i++) { real[i].__eqil = true; texts.push(real[i].textContent); values.push(real[i].value); }
            if (MODE !== "blank" && !sel.querySelector("optgroup") && !ordinal(texts, values)) {
                var order = permute(real, gameKey(sel.id || sel.name || "", values));
                for (i = 0; i < order.length; i++) { sel.appendChild(order[i]); }
            }
            sel.__eqilDef = before;
            sel.__eqilPh = ph ? ph.value : "";
            if (wasUser && prev && prev !== sel.__eqilPh && hasValue(sel, prev)) { sel.value = prev; }
            else if (shown(sel)) { clear(sel, ph); sel.__eqilUser = false; }
            else { sel.value = before; sel.__eqilUser = false; }
        } else {
            if (roundChanged) { sel.__eqilUser = false; }
            if (!sel.__eqilUser && sel.value !== none && sel.value === sel.__eqilDef && shown(sel)) { clear(sel, ph); }
        }
        if (ph && ph.getAttribute("data-eqil-ph") !== null) {
            var label = "— " + TXT[lang()][0] + " —";
            if (ph.textContent !== label) { ph.textContent = label; }
        }
        if (!sel.__eqilBound) {
            sel.__eqilBound = true;
            sel.addEventListener("change", function () {
                sel.__eqilUser = true;
                sel.__eqilLast = sel.value;
                sel.classList.remove("eqil-missing");
            });
        }
        sel.__eqilLast = sel.value;
    }

    function checkedValue(els) {
        for (var i = 0; i < els.length; i++) { if (els[i].checked) { return els[i].value; } }
        return null;
    }
    function setRadio(els, v) { for (var i = 0; i < els.length; i++) { els[i].checked = (v !== null && els[i].value === v); } }
    function radioItems(els) {
        var box = els[0].parentElement, i, ok;
        while (box) {
            ok = true;
            for (i = 0; i < els.length; i++) { if (!box.contains(els[i])) { ok = false; break; } }
            if (ok) { break; }
            box = box.parentElement;
        }
        if (!box) { return null; }
        var items = [];
        for (i = 0; i < els.length; i++) {
            var it = els[i];
            while (it && it.parentElement !== box) { it = it.parentElement; }
            if (!it || items.indexOf(it) >= 0) { return null; }
            items.push(it);
        }
        var kids = Array.prototype.slice.call(box.children), pos = items.map(function (x) { return kids.indexOf(x); }).sort(function (a, b) { return a - b; });
        for (i = 1; i < pos.length; i++) { if (pos[i] !== pos[i - 1] + 1) { return null; } }
        return { box: box, items: items, after: kids[pos[pos.length - 1]].nextSibling };
    }
    function doRadios(name, els, roundChanged) {
        if (els.length < 2) { return; }
        var g = groups[name] || (groups[name] = {}), fresh = false, i, vis = false;
        for (i = 0; i < els.length; i++) { if (!els[i].__eqil) { fresh = true; } if (shown(els[i])) { vis = true; } }
        g.els = els;
        var cur = checkedValue(els);
        if (fresh) {
            var wasUser = g.user && !roundChanged, texts = [], values = [];
            for (i = 0; i < els.length; i++) {
                els[i].__eqil = true;
                values.push(els[i].value);
                var lab = els[i].closest ? els[i].closest("label") : null;
                texts.push(lab ? lab.textContent : els[i].value);
                if (!els[i].__eqilBound) {
                    els[i].__eqilBound = true;
                    els[i].addEventListener("change", function () {
                        g.user = true;
                        g.last = checkedValue(g.els);
                        var r = radioItems(g.els);
                        if (r) { r.box.classList.remove("eqil-missing"); }
                    });
                }
            }
            if (MODE !== "blank" && !ordinal(texts, values)) {
                var r = radioItems(els);
                if (r) {
                    var order = permute(r.items, gameKey(name, values));
                    for (i = 0; i < order.length; i++) { r.box.insertBefore(order[i], r.after); }
                }
            }
            g.def = cur;
            if (wasUser && g.last !== null && g.last !== undefined) { setRadio(els, g.last); }
            else if (vis) { setRadio(els, null); g.user = false; }
            else { g.user = false; }
        } else {
            if (roundChanged) { g.user = false; }
            if (!g.user && cur !== null && cur === g.def && vis) { setRadio(els, null); }
        }
        g.managed = true;
        g.last = checkedValue(els);
    }

    function pass() {
        queued = false;
        var rk = roundKey(), rc = lastRound !== null && rk !== lastRound, i;
        lastRound = rk;
        var sels = document.querySelectorAll("select");
        for (i = 0; i < sels.length; i++) { if (!skipped(sels[i])) { doSelect(sels[i], rc); } }
        var byName = {}, rads = document.querySelectorAll("input[type=radio]");
        for (i = 0; i < rads.length; i++) {
            if (skipped(rads[i]) || !rads[i].name) { continue; }
            (byName[rads[i].name] = byName[rads[i].name] || []).push(rads[i]);
        }
        for (var n in byName) { doRadios(n, byName[n], rc); }
    }
    function schedule() { if (!queued) { queued = true; later(pass, 0); } }

    function missing() {
        var out = [], sels = document.querySelectorAll("select"), i;
        for (i = 0; i < sels.length; i++) {
            var s = sels[i];
            if (s.__eqilManaged && !s.disabled && s.value === (s.__eqilPh || "") && shown(s)) { out.push(s); }
        }
        for (var n in groups) {
            var g = groups[n];
            if (!g.managed || !g.els || checkedValue(g.els) !== null) { continue; }
            var live = false;
            for (i = 0; i < g.els.length; i++) { if (!g.els[i].disabled && g.els[i].isConnected !== false && shown(g.els[i])) { live = true; } }
            if (live) { var r = radioItems(g.els); out.push(r ? r.box : g.els[0]); }
        }
        return out;
    }
    function fillHidden() {
        var sels = document.querySelectorAll("select"), i;
        for (i = 0; i < sels.length; i++) {
            var s = sels[i];
            if (s.__eqilManaged && s.value === (s.__eqilPh || "") && s.__eqilDef && s.__eqilDef !== s.value && (s.disabled || !shown(s)) && hasValue(s, s.__eqilDef)) { s.value = s.__eqilDef; }
        }
        for (var n in groups) {
            var g = groups[n];
            if (g.managed && g.els && g.def !== null && g.def !== undefined && checkedValue(g.els) === null && !shown(g.els[0])) { setRadio(g.els, g.def); }
        }
    }
    function flag(els) {
        if (!styled) {
            styled = true;
            var st = document.createElement("style");
            st.textContent = ".eqil-missing{outline:2px solid #dc2626 !important;outline-offset:2px}";
            (document.head || document.body).appendChild(st);
        }
        for (var i = 0; i < els.length; i++) { els[i].classList.add("eqil-missing"); }
        try {
            var f = sim();
            if (f && f.uiManager && typeof f.uiManager.showNotification === "function") { f.uiManager.showNotification(TXT[lang()][1], "warning"); }
        } catch (e) {}
    }

    function wrapCheck(orig) {
